        const lead = clamp(d / (speed + 0.1), 0, 1.2) * 0.6;
        const tx = t.x + t.vx * lead;
        const ty = t.y + t.vy * lead;
        const burst = d < 5 ? 1.2 : 1;
        this.steerTo(b, tx, ty, speed * burst, 0.4);
        dvx = b.dirX;
        dvy = b.dirY;
        break;
      }
      case 'wander': {
        const d = this.steerTo(b, b.gx, b.gy, speed * 0.5, 1.5);
        dvx = b.dirX;
        dvy = b.dirY;
