  ctx.lineTo(sx + rr * 0.1, sy - rr * 1.3);
  ctx.stroke();

  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(sx, sy, rr, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(38,92,30,0.55)';
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.fillStyle = 'rgba(255,255,240,0.75)';
