+
+const BODY = { A: 1.28, B: 0.95, C: 0.9 };
+
+const LOBES = [
+  { o: [0.5, 0.1, 0.02], r: [0.62, 0.9, 0.92] },
+  { o: [0.0, 0.0, 0.0], r: [0.78, 1.0, 1.0] },
+  { o: [-0.5, 0.13, -0.02], r: [0.6, 0.86, 0.88] },
