+    }
+    case 'startled': {
+      sq += 0.2 * (1 - p);
+      jump = Math.sin(clamp(p * 1.6, 0, 1) * Math.PI) * 0.9;
+      glow = 1 - p;
+      glowKind = 5;
+      look.eyes = 'wide';
+      look.mouth = 'o';
+      look.sweat = true;
