+        ctx.fill();
+        break;
+      case 'sad':
+        ctx.beginPath();
+        ctx.moveTo(-0.1, -0.06);
+        ctx.quadraticCurveTo(0, 0.05, 0.1, -0.06);
+        ctx.stroke();
+        break;
