+  if (look.sweat) {
+    const sv = facePlane(ctx, cam, 0.5, 0.9, 0.7, 0.75, 0.1 + 0.95, 0.75);
+    if (sv >= 0.06) {
+      ctx.fillStyle = 'rgba(150,215,255,0.95)';
+      ctx.beginPath();
+      ctx.moveTo(0, 0.2);
+      ctx.quadraticCurveTo(0.14, -0.02, 0, -0.1);
+      ctx.quadraticCurveTo(-0.14, -0.02, 0, 0.2);
