+      if (f < -0.05) {
+        started = false;
+        continue;
+      }
+      if (!started) {
+        ctx.moveTo(this.wallBottom.x[i], this.wallBottom.y[i]);
+        started = true;
+      } else ctx.lineTo(this.wallBottom.x[i], this.wallBottom.y[i]);
+    }
+    ctx.stroke();
+  }
+
+  private drawGround(ctx: CanvasRenderingContext2D, R: number) {
+    if (!this.ground) return;
