+    ctx.lineWidth = 2;
+    ctx.beginPath();
+    ctx.moveTo(a.sx - 6, y - 6);
+    ctx.lineTo(a.sx + 6, y - 6);
+    ctx.lineTo(a.sx, y + 3);
+    ctx.closePath();
+    ctx.stroke();
+    ctx.fill();
+  }
+
+  private drawEnergyBar(ctx: CanvasRenderingContext2D, b: Blob, a: Anim, thr: number) {
+    if (b.dead) return;
+    const w = Math.max(20, this.cam.scale * 1.7);
+    const h = 4;
+    const x = a.sx - w / 2;
+    const y = a.sy - a.radius * 1.55 - 8;
