+    ctx.fill();
+    ctx.fillStyle = k > 0.55 ? '#59d36a' : k > 0.28 ? '#ffc94a' : '#ff6b5d';
+    ctx.beginPath();
+    ctx.roundRect(x, y, Math.max(2, w * k), h, 2);
+    ctx.fill();
+  }
