  });
}

/** Indices of confirmed peaks: a peak counts once the series has fallen by at least `swing` after it. */
function findPeaks(v: number[], swing: number) {
  const peaks: number[] = [];
  if (v.length < 3) return peaks;
  let dir = 0;
  let hi = v[0];
  let hiI = 0;
  let lo = v[0];
  for (let i = 1; i < v.length; i++) {
