    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(lx, ly, 5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.textAlign = lx > px + pw - 40 ? 'right' : 'left';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText('now', lx + (lx > px + pw - 40 ? -10 : 10), ly - 10);

