        ctx.arc(x, Y(l.value(s)), 4.4, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = l.color;
        ctx.beginPath();
        ctx.arc(x, Y(l.value(s)), 3, 0, Math.PI * 2);
        ctx.fill();
      }
