];

export const SPEED_SPEC: ParamSpec = {
  key: 'speed',
  label: 'Simulation speed',
  hint: 'How many simulated seconds pass per real second.',
  min: 0.5,
  max: 40,
  step: 0.5,
  unit: '×',
  digits: 1,
};

export const REBUILD_KEYS: ParamKey[] = ['trees', 'blueStart', 'redStart', 'worldSize', 'seed'];

export interface Preset {
  id: string;
  name: string;
  blurb: string;
  emoji: string;
  params: Partial<Params>;
}

export const PRESETS: Preset[] = [
  {
    id: 'balanced',
    name: 'Balanced garden',
    blurb: 'Blue and red rise and fall in a lagged dance.',
    emoji: '🌿',
    params: {},
  },
  {
    id: 'fruit-rich',
    name: 'Fruit-rich garden',
    blurb: 'Plenty of fruit. Blue booms first.',
    emoji: '🍏',
    params: { fruitGrowth: 1.8, fruitLimit: 8, fruitDelay: 4, trees: 12 },
  },
  {
    id: 'red-heavy',
    name: 'Red-heavy garden',
    blurb: 'Red crowd at the start. Blue dips first, red fades later.',
    emoji: '🍓',
    params: { redStart: 14, blueStart: 46 },
  },
  {
    id: 'fragile',
    name: 'Fragile balance',
    blurb: 'Quick, touchy reds. Swings get wild and may collapse.',
    emoji: '🫧',
    params: { redContact: 1.2, redSpeed: 3.4, redVision: 10, redPause: 2 },
  },
  {
    id: 'low-fruit',
    name: 'Low-fruit garden',
    blurb: 'Little fruit keeps the whole garden small.',
    emoji: '🥀',
    params: { fruitGrowth: 0.7, fruitLimit: 4, fruitDelay: 12, trees: 5, blueStart: 25, redStart: 4 },
  },
];

export interface Pt {
  x: number;
  y: number;
  d: number;
}

export class Camera {
  yaw = 0.7;
  pitch = 0.92;
  zoom = 1;
  width = 800;
  height = 600;
  cx = 400;
  cy = 300;
  scale = 10;
  radius = 24;

  private c = 1;
  private s = 0;
  private cp = 0;
  private sp = 1;

  viewX = 0;
  viewY = 0;
  viewZ = 1;

  setViewport(width: number, height: number, radius: number) {
    this.width = width;
    this.height = height;
    this.radius = radius;
    this.update();
  }

  update() {
    this.c = Math.cos(this.yaw);
    this.s = Math.sin(this.yaw);
    this.cp = Math.cos(this.pitch);
    this.sp = Math.sin(this.pitch);
    const R = this.radius;
    const wallDepth = 3.2;
    const treeRise = 5.2;
    const fitW = (this.width * 0.94) / (2 * R + 2);
    const fitH = (this.height * 0.94) / (2 * R * this.sp + (wallDepth + treeRise) * this.cp + 2);
    this.scale = Math.min(fitW, fitH) * this.zoom;
    this.cx = this.width / 2;
    this.cy = this.height / 2 + ((treeRise - wallDepth) / 2) * this.cp * this.scale;
    this.viewX = -this.cp * this.s;
    this.viewY = -this.cp * this.c;
    this.viewZ = this.sp;
  }

  project(x: number, y: number, z: number, out: Pt) {
    const rx = x * this.c - y * this.s;
    const ry = x * this.s + y * this.c;
    out.x = this.cx + rx * this.scale;
    out.y = this.cy - (ry * this.sp + z * this.cp) * this.scale;
    out.d = ry * this.cp - z * this.sp;
    return out;
  }

  /** Screen-space direction of a world-space vector (no translation). */
  dir(nx: number, ny: number, nz: number, out: { x: number; y: number }) {
    const rx = nx * this.c - ny * this.s;
    const ry = nx * this.s + ny * this.c;
    out.x = rx * this.scale;
    out.y = -(ry * this.sp + nz * this.cp) * this.scale;
    return out;
  }

  depthOf(x: number, y: number) {
    return (x * this.s + y * this.c) * this.cp;
  }

  /** Affine matrix that maps ground (x, y) to screen pixels. */
  groundMatrix(): [number, number, number, number, number, number] {
    return [this.scale * this.c, -this.scale * this.sp * this.s, -this.scale * this.s, -this.scale * this.sp * this.c, this.cx, this.cy];
  }

  /** Approximate inverse for ground plane picking. */
  unproject(sx: number, sy: number) {
    const rx = (sx - this.cx) / this.scale;
    const ry = -(sy - this.cy) / (this.scale * this.sp);
    return { x: rx * this.c + ry * this.s, y: -rx * this.s + ry * this.c };
  }

  orbit(dx: number, dy: number) {
    this.yaw += dx * 0.0085;
    this.pitch = Math.max(0.42, Math.min(1.32, this.pitch + dy * 0.006));
    this.update();
  }
}

/* ------------------------------------------------------------------ */

export type Kind = 'blue' | 'red';

export type Action =
  | 'seek'
  | 'gather'
  | 'wander'
  | 'idle'
  | 'flee'
  | 'spread'
  | 'eat'
  | 'startled'
  | 'bud'
  | 'hunt'
  | 'nuzzle'
  | 'pause';

export type SlotState = 'ripe' | 'growing' | 'resting' | 'eating';

export interface Slot {
  state: SlotState;
  progress: number;
  delay: number;
  rate: number;
  claim: Blob | null;
  eat: number;
}

export interface Tree {
  id: number;
  x: number;
  y: number;
  seed: number;
  scale: number;
  slots: Slot[];
  shake: number;
}

export interface Traits {
  speed: number;
  vision: number;
}

export interface Blob {
  id: number;
  kind: Kind;
  x: number;
  y: number;
  px: number;
  py: number;
  vx: number;
  vy: number;
  heading: number;
  pheading: number;
  energy: number;
  age: number;
  traits: Traits;
  family: number;
  generation: number;
  parent: number;
  kids: number;
  action: Action;
  lock: number;
  lockTotal: number;
  think: number;
  target: Blob | null;
  tree: Tree | null;
  slot: Slot | null;
  slotIdx: number;
  gx: number;
  gy: number;
  dirX: number;
  dirY: number;
  sepX: number;
  sepY: number;
  stress: number;
  hunter: Blob | null;
  ignore: Blob | null;
  ignoreT: number;
  chase: number;
  idle: number;
  immune: number;
  cooldown: number;
  memTree: Tree | null;
  memX: number;
  memY: number;
  hasMem: boolean;
  dying: number;
  dead: boolean;
  cause: '' | 'starved' | 'drained' | 'old';
  lifespan: number;
  eaten: number;
  contacts: number;
  bornAt: number;
  orbit: number;
  personality: number;
  hueShift: number;
}

