+.group.tone-blue,
+.slider.tone-blue {
+  --tone: var(--blue);
+}
+.group.tone-red,
+.slider.tone-red {
+  --tone: var(--red);
+}
+.slider.tone-world {
+  --tone: var(--dusk);
+}
+
+.group summary {
+  list-style: none;
+  cursor: pointer;
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  padding: 11px 14px;
+  font-weight: 800;
+  font-size: 14px;
+  border-radius: 16px;
+  user-select: none;
+}
+
+.group summary::-webkit-details-marker {
+  display: none;
+}
+
+.group summary::after {
+  content: '';
+  margin-left: auto;
+  width: 8px;
+  height: 8px;
+  border-right: 2px solid var(--faint);
+  border-bottom: 2px solid var(--faint);
+  transform: rotate(45deg);
+  transition: transform 0.2s;
+}
+
+.group[open] summary::after {
+  transform: rotate(-135deg);
+}
+
+.group .dot {
+  width: 12px;
+  height: 12px;
+  border-radius: 50%;
+  background: var(--tone);
+  box-shadow: 0 0 0 4px color-mix(in srgb, var(--tone) 20%, transparent);
+}
+
+.group-body {
+  display: grid;
+  gap: 12px;
+  padding: 2px 14px 14px;
+}
+
+.slider {
+  display: grid;
+  gap: 5px;
+}
+
+.slider-top {
+  display: flex;
+  justify-content: space-between;
+  align-items: baseline;
+  font-size: 13.5px;
+  font-weight: 650;
+}
+
+.slider output {
+  font-variant-numeric: tabular-nums;
+  font-weight: 800;
+  color: var(--ink);
+}
+
+.slider output small {
+  font-weight: 650;
+  color: var(--faint);
+  margin-left: 3px;
+}
+
+.slider-hint {
+  font-size: 11.5px;
+  color: var(--faint);
+}
+
+input[type='range'] {
+  -webkit-appearance: none;
+  appearance: none;
+  width: 100%;
+  height: 22px;
+  background: transparent;
+  margin: 0;
+  cursor: pointer;
+}
+
+input[type='range']::-webkit-slider-runnable-track {
+  height: 8px;
+  border-radius: 999px;
+  background: linear-gradient(to right, var(--tone) var(--p, 0%), rgba(90, 70, 120, 0.14) var(--p, 0%));
+}
+
+input[type='range']::-moz-range-track {
+  height: 8px;
+  border-radius: 999px;
+  background: rgba(90, 70, 120, 0.14);
+}
+
+input[type='range']::-moz-range-progress {
+  height: 8px;
+  border-radius: 999px;
+  background: var(--tone);
+}
+
+input[type='range']::-webkit-slider-thumb {
+  -webkit-appearance: none;
+  width: 20px;
+  height: 20px;
+  margin-top: -6px;
+  border-radius: 50%;
+  background: #fff;
+  border: 3px solid var(--tone);
+  box-shadow: 0 2px 5px rgba(60, 40, 90, 0.3);
+  transition: transform 0.12s;
+}
+
+input[type='range']::-moz-range-thumb {
+  width: 14px;
+  height: 14px;
+  border-radius: 50%;
+  background: #fff;
+  border: 3px solid var(--tone);
+  box-shadow: 0 2px 5px rgba(60, 40, 90, 0.3);
+}
+
+input[type='range']:active::-webkit-slider-thumb {
+  transform: scale(1.15);
+}
+
+.seed-row {
+  display: flex;
+  align-items: center;
+  gap: 8px;
+  font-size: 13.5px;
+  font-weight: 650;
+}
+
+.seed-row input {
+  flex: 1;
+  min-width: 0;
+  height: 36px;
+  border-radius: 12px;
+  border: 1px solid var(--line);
+  background: #fff;
+  padding: 0 12px;
+  font-variant-numeric: tabular-nums;
+  font-weight: 700;
+}
+
+.toggle {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  font-size: 13.5px;
+  font-weight: 600;
+  cursor: pointer;
+}
+
+.toggle input {
+  width: 18px;
+  height: 18px;
+  accent-color: var(--dusk);
+}
+
+/* ------------------------------------------------------------- charts */
+
+.charts {
+  display: grid;
+  grid-template-columns: repeat(6, minmax(0, 1fr));
+  gap: 18px;
+}
+
+.charts > .card {
+  grid-column: span 3;
+}
+
+.charts > .card.wide {
+  grid-column: span 4;
+}
+
+.charts > .card:nth-child(2) {
+  grid-column: span 2;
+}
+
+.chart-block {
+  display: grid;
+  gap: 8px;
+}
+
+.chart-head {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  justify-content: space-between;
+  gap: 8px 14px;
+}
+
+.legend {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 6px 14px;
+  font-size: 13px;
+  font-weight: 650;
+}
+
+.legend-item {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  font-variant-numeric: tabular-nums;
+}
+
+.legend-item i {
+  width: 12px;
+  height: 12px;
+  border-radius: 4px;
+}
+
+.legend-item b {
+  font-weight: 800;
+}
+
+.legend-item em {
+  font-style: normal;
+  color: var(--faint);
+  font-weight: 600;
+  font-size: 12px;
+}
+
+.legend-item.plain {
+  color: var(--muted);
+  font-weight: 600;
+}
+
+.chart-canvas {
+  width: 100%;
+  display: block;
+  border-radius: 12px;
+  touch-action: pan-y;
+}
+
+.chart-note {
+  font-size: 12.5px;
+  line-height: 1.4;
+  color: var(--muted);
+}
+
+.seg {
+  display: inline-flex;
+  padding: 3px;
+  gap: 2px;
+  background: rgba(90, 70, 120, 0.09);
+  border-radius: 999px;
+}
+
+.seg button {
+  border: 0;
+  background: transparent;
+  padding: 5px 12px;
+  border-radius: 999px;
+  font-size: 12.5px;
+  font-weight: 700;
+  color: var(--muted);
+}
+
+.seg button.on {
+  background: #fff;
+  color: var(--ink);
+  box-shadow: 0 1px 3px rgba(60, 40, 90, 0.25);
+}
+
+/* ------------------------------------------------------------ summary */
+
+.summary {
+  --tone: var(--dusk);
+  display: grid;
+  gap: 12px;
+}
+
+.summary.tone-good {
+  --tone: var(--fruit);
+}
+.summary.tone-warn {
+  --tone: #e0962b;
+}
+.summary.tone-bad {
+  --tone: var(--red);
+}
+
+.verdict {
+  border-left: 5px solid var(--tone);
+  background: color-mix(in srgb, var(--tone) 10%, #fffdf8);
+  border-radius: 6px 14px 14px 6px;
+  padding: 10px 14px;
+}
+
+.verdict strong {
+  display: block;
+  font-size: 17px;
+  letter-spacing: -0.01em;
+  margin-bottom: 3px;
+}
+
+.verdict p {
+  font-size: 13.5px;
+  line-height: 1.45;
+  color: var(--muted);
+}
+
+.story {
+  list-style: none;
+  margin: 0;
+  padding: 0;
+  display: grid;
+  gap: 8px;
+}
+
+.story li {
+  display: grid;
+  grid-template-columns: 12px 1fr;
+  gap: 9px;
+  align-items: start;
+  font-size: 13.5px;
+  line-height: 1.42;
+}
+
+.story li i {
+  width: 10px;
+  height: 10px;
+  margin-top: 5px;
+  border-radius: 50%;
+  background: var(--faint);
+}
+
+.story .mark-blue i {
+  background: var(--blue);
+}
+.story .mark-red i {
+  background: var(--red);
+}
+.story .mark-fruit i {
+  background: var(--fruit);
+}
+.story .mark-wave i {
+  background: var(--dusk);
+}
+
+.facts {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(112px, 1fr));
+  gap: 8px;
+  margin: 0;
+}
+
+.facts div {
+  background: rgba(248, 241, 226, 0.65);
+  border-radius: 12px;
+  padding: 8px 10px;
+}
+
+.facts dt {
+  font-size: 11px;
+  font-weight: 800;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  color: var(--muted);
+}
+
+.facts dd {
+  margin: 1px 0 0;
+  font-size: 19px;
+  font-weight: 800;
+  font-variant-numeric: tabular-nums;
+}
+
+.facts small {
+  display: block;
+  color: var(--muted);
+  font-size: 11.5px;
+  line-height: 1.3;
+}
+
+/* ---------------------------------------------------------- inspector */
+
+.inspector {
+  --tone: var(--blue);
+  position: absolute;
+  right: 14px;
+  top: 60px;
+  width: 292px;
+  max-height: calc(100% - 76px);
+  overflow: auto;
+  padding: 14px;
+  display: grid;
+  gap: 12px;
+  border-radius: 20px;
+  background: rgba(255, 253, 248, 0.94);
+  backdrop-filter: blur(10px);
+  box-shadow: 0 14px 34px -14px rgba(60, 40, 20, 0.5), 0 1px 3px rgba(60, 40, 20, 0.15);
+  scrollbar-width: thin;
+  animation: pop 0.22s ease-out;
+}
+
+.inspector.is-red {
+  --tone: var(--red);
+}
+
+.inspector.is-dead {
+  filter: saturate(0.5);
+}
+
+@keyframes pop {
+  from {
+    opacity: 0;
+    transform: translateY(6px) scale(0.98);
+  }
+}
+
+.inspector header {
+  display: flex;
+  align-items: center;
+  gap: 12px;
+}
+
+.portrait {
+  width: 44px;
+  height: 44px;
+  border-radius: 50%;
+  background: radial-gradient(circle at 34% 28%, #fff 0 8%, color-mix(in srgb, var(--tone) 55%, #fff) 30%, var(--tone) 75%);
+  box-shadow: 0 4px 10px -4px var(--tone);
+  flex: none;
+}
+
+.who {
+  flex: 1;
+  min-width: 0;
+}
+
+.who h3 {
+  font-size: 19px;
+  letter-spacing: -0.01em;
+  line-height: 1.15;
+}
+
+.pill {
+  display: inline-block;
+  margin-top: 3px;
+  padding: 2px 10px;
+  border-radius: 999px;
+  font-size: 12px;
+  font-weight: 750;
+  color: #fff;
+  background: var(--tone);
+}
+
+.inspector .icon-btn {
+  font-size: 22px;
+  line-height: 1;
+  width: 32px;
+  height: 32px;
+}
+
+.action {
+  display: grid;
+  gap: 3px;
+  padding: 10px 12px;
+  border-radius: 14px;
+  background: color-mix(in srgb, var(--tone) 9%, #fffdf8);
+}
+
+.action strong {
+  font-size: 15px;
+}
+
+.action > span {
+  font-size: 12.5px;
+  line-height: 1.4;
+  color: var(--muted);
+}
+
+.lock {
+  margin-top: 6px;
+  display: grid;
+  gap: 4px;
+}
+
+.lock-row {
+  display: flex;
+  justify-content: space-between;
+  align-items: baseline;
+  font-size: 12.5px;
+  font-weight: 700;
+}
+
+.lock-row b {
+  font-variant-numeric: tabular-nums;
+}
+
+.lock-row em,
+.grid em,
+.trait em {
+  font-style: normal;
+  color: var(--faint);
+  font-weight: 600;
+}
+
+.bar {
+  position: relative;
+  height: 9px;
+  border-radius: 999px;
+  background: rgba(90, 70, 120, 0.13);
+}
+
+.bar i {
+  position: absolute;
+  left: 0;
+  top: 0;
+  bottom: 0;
+  border-radius: inherit;
+  background: var(--tone);
+}
+
+.bar.energy i {
+  background: linear-gradient(90deg, #ff9a6b, #ffd84f 45%, #6fd16a);
+}
+
+.bar s {
+  position: absolute;
+  top: -3px;
+  bottom: -3px;
+  width: 3px;
+  margin-left: -1px;
+  border-radius: 2px;
+  background: var(--ink);
+}
+
+.stat {
+  display: grid;
+  gap: 6px;
+}
+
+.grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 8px;
+  margin: 0;
+}
+
+.grid div {
+  background: rgba(248, 241, 226, 0.65);
+  border-radius: 12px;
+  padding: 7px 10px;
+}
+
+.grid dt {
+  font-size: 11px;
+  font-weight: 800;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  color: var(--muted);
+}
+
+.grid dd {
+  margin: 1px 0 0;
+  font-size: 15px;
+  font-weight: 800;
+  font-variant-numeric: tabular-nums;
+}
+
+.inspector h4 {
+  font-size: 11.5px;
+  font-weight: 800;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: var(--muted);
+  margin-bottom: 5px;
+}
+
+.trait {
+  display: grid;
+  grid-template-columns: 1fr auto auto;
+  gap: 10px;
+  font-size: 13.5px;
+  font-weight: 650;
+  padding: 3px 0;
+  font-variant-numeric: tabular-nums;
+}
+
+.trait b {
+  font-weight: 800;
+}
+
+.trait em {
+  min-width: 52px;
+  text-align: right;
+}
+
+.family p {
+  font-size: 13px;
+  line-height: 1.45;
+}
+
+.family p + p {
+  margin-top: 3px;
+}
+
+.muted {
+  color: var(--muted);
+}
+
+.link {
+  border: 0;
+  background: none;
+  padding: 0;
+  font-weight: 800;
+  color: var(--dusk);
+  text-decoration: underline;
+  text-underline-offset: 2px;
+}
+
+/* --------------------------------------------------------- responsive */
+
+@media (max-width: 1180px) {
+  .charts > .card,
+  .charts > .card.wide,
+  .charts > .card:nth-child(2) {
+    grid-column: span 6;
+  }
+}
+
+@media (max-width: 900px) {
+  .layout {
+    grid-template-columns: 1fr;
+  }
+  .controls {
+    position: static;
+    max-height: none;
+  }
+  .charts > .card {
+    grid-column: span 6;
+  }
+}
+
+@media (max-width: 640px) {
+  .app {
+    padding: 12px 12px 32px;
+  }
+  .inspector {
+    left: 10px;
+    right: 10px;
+    top: auto;
+    bottom: 10px;
+    width: auto;
+    max-height: 62%;
+  }
+  .hud {
+    max-width: 100%;
+    top: 58px;
+  }
+  .stage-hint {
+    display: none;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  * {
+    animation: none !important;
+    transition: none !important;
+  }
+}

success.afterFullFileContent:
:root {
  --ink: #3b3350;
  --muted: #6f6785;
  --faint: #9a92ad;
  --cream: #f8f1e2;
  --card: #fffdf8;
  --line: #eadfc9;
  --blue: #3f7cf0;
  --red: #ef4d64;
  --fruit: #4aa957;
  --dusk: #6f57d9;
  --shadow: 0 1px 0 rgba(255, 255, 255, 0.9) inset, 0 8px 24px -12px rgba(80, 55, 20, 0.35), 0 1px 3px rgba(80, 55, 20, 0.12);
  --radius: 20px;
  font-family: ui-rounded, 'SF Pro Rounded', 'Nunito', 'Segoe UI', system-ui, sans-serif;
  color: var(--ink);
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
}

body {
  background:
    radial-gradient(1100px 600px at 8% -10%, rgba(255, 205, 170, 0.5), transparent 60%),
    radial-gradient(900px 600px at 100% 0%, rgba(190, 215, 255, 0.45), transparent 60%),
    radial-gradient(900px 700px at 60% 110%, rgba(200, 240, 200, 0.5), transparent 60%),
    var(--cream);
  background-attachment: fixed;
  -webkit-font-smoothing: antialiased;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

:focus-visible {
  outline: 3px solid rgba(111, 87, 217, 0.55);
  outline-offset: 2px;
}

h1,
h2,
h3,
h4,
p {
  margin: 0;
}

.app {
  max-width: 1560px;
  margin: 0 auto;
  padding: 18px 20px 40px;
}

/* ------------------------------------------------------------ top bar */

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px 24px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

.topbar h1 {
  font-size: clamp(26px, 3.2vw, 36px);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.presets {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  border: 1px solid var(--line);
  background: var(--card);
  border-radius: 999px;
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 650;
  box-shadow: 0 1px 2px rgba(80, 55, 20, 0.1);
  transition: transform 0.15s, background 0.15s, box-shadow 0.15s;
}

.chip:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 10px -4px rgba(80, 55, 20, 0.3);
}

.chip.on {
  background: var(--ink);
  border-color: var(--ink);
  color: #fff8ea;
}

.chip.custom {
  border-style: dashed;
  background: transparent;
  color: var(--muted);
  box-shadow: none;
}

/* ------------------------------------------------------------- layout */

.layout {
  display: grid;
  grid-template-columns: 300px minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}

.controls {
  position: sticky;
  top: 12px;
  max-height: calc(100vh - 24px);
  overflow: auto;
  padding: 14px;
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  scrollbar-width: thin;
}

.preset-blurb {
  font-size: 13.5px;
  line-height: 1.4;
  color: var(--muted);
  padding: 4px 4px 12px;
}

.main {
  display: grid;
  gap: 18px;
  min-width: 0;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px 18px 14px;
  min-width: 0;
}

.card > h2 {
  font-size: 12.5px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 10px;
}

/* -------------------------------------------------------------- stage */

.stage-card {
  padding: 0;
  overflow: hidden;
}

.stage {
  position: relative;
  height: clamp(460px, 66vh, 760px);
  background:
    radial-gradient(70% 60% at 50% 45%, #fff6dd 0%, #f6e7c8 55%, #efdcb6 100%);
  overflow: hidden;
}

.world-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
  outline-offset: -4px;
}

.hud {
  position: absolute;
  left: 14px;
  top: 14px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  pointer-events: none;
  max-width: calc(100% - 180px);
}

.hud-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 12px;
  border-radius: 999px;
  background: rgba(255, 253, 248, 0.86);
  backdrop-filter: blur(6px);
  font-size: 13.5px;
  font-weight: 650;
  box-shadow: 0 2px 8px -3px rgba(80, 55, 20, 0.35);
  font-variant-numeric: tabular-nums;
}

.hud-chip b {
  font-weight: 800;
}

.hud-chip small {
  color: var(--faint);
  font-size: 12px;
  margin-left: -4px;
}

.hud-chip i {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.d-time {
  background: var(--ink);
}
.d-blue {
  background: var(--blue);
}
.d-red {
  background: var(--red);
}
.d-fruit {
  background: var(--fruit);
}

.hud-chip.paused {
  background: var(--ink);
  color: #fff8ea;
}

.view-tools {
  position: absolute;
  right: 14px;
  top: 14px;
  display: flex;
  gap: 8px;
}

.stage-hint {
  position: absolute;
  left: 16px;
  bottom: 12px;
  font-size: 12.5px;
  font-weight: 600;
  color: rgba(59, 51, 80, 0.62);
  pointer-events: none;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.7);
}

.icon-btn {
  display: inline-grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: var(--card);
  padding: 0;
  transition: transform 0.15s, background 0.15s;
}

.icon-btn:hover {
  transform: translateY(-1px);
  background: #fff;
}

.icon-btn.glass {
  background: rgba(255, 253, 248, 0.88);
  backdrop-filter: blur(6px);
  border-color: rgba(255, 255, 255, 0.7);
  box-shadow: 0 2px 8px -3px rgba(80, 55, 20, 0.35);
}

/* ---------------------------------------------------------- transport */

.transport {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px 24px;
  padding: 12px 16px 14px;
  border-top: 1px solid var(--line);
}

.buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 40px;
  padding: 0 16px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: #fff;
  font-weight: 700;
  font-size: 14px;
  box-shadow: 0 1px 2px rgba(80, 55, 20, 0.12);
  transition: transform 0.15s, box-shadow 0.15s;
}

.btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 12px -6px rgba(80, 55, 20, 0.4);
}

.btn:active {
  transform: translateY(1px);
}

.btn.primary {
  background: var(--dusk);
  border-color: var(--dusk);
  color: #fff;
  min-width: 104px;
  justify-content: center;
}

.speed {
  display: flex;
  align-items: center;
  gap: 14px;
  flex: 1 1 320px;
  max-width: 560px;
}

.speed .slider {
  flex: 1;
  min-width: 140px;
}

.quick {
  display: flex;
  gap: 4px;
}

.mini {
  min-width: 36px;
  height: 30px;
  padding: 0 8px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: #fff;
  font-size: 13px;
  font-weight: 700;
}

.mini.on {
  background: var(--ink);
  border-color: var(--ink);
  color: #fff8ea;
}

/* ------------------------------------------------------------ sliders */

.group {
  --tone: var(--dusk);
  border-radius: 16px;
  margin-bottom: 8px;
  background: rgba(248, 241, 226, 0.5);
  border: 1px solid rgba(234, 223, 201, 0.7);
}

.group.tone-fruit,
.slider.tone-fruit {
  --tone: var(--fruit);
}
.group.tone-blue,
.slider.tone-blue {
  --tone: var(--blue);
}
.group.tone-red,
.slider.tone-red {
  --tone: var(--red);
}
.slider.tone-world {
  --tone: var(--dusk);
}

.group summary {
  list-style: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 14px;
  font-weight: 800;
  font-size: 14px;
  border-radius: 16px;
  user-select: none;
}

.group summary::-webkit-details-marker {
  display: none;
}

.group summary::after {
  content: '';
  margin-left: auto;
  width: 8px;
  height: 8px;
  border-right: 2px solid var(--faint);
  border-bottom: 2px solid var(--faint);
  transform: rotate(45deg);
  transition: transform 0.2s;
}

.group[open] summary::after {
  transform: rotate(-135deg);
}

.group .dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--tone);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--tone) 20%, transparent);
}

.group-body {
  display: grid;
  gap: 12px;
  padding: 2px 14px 14px;
}

.slider {
  display: grid;
  gap: 5px;
}

.slider-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 13.5px;
  font-weight: 650;
}

.slider output {
  font-variant-numeric: tabular-nums;
  font-weight: 800;
  color: var(--ink);
}

.slider output small {
  font-weight: 650;
  color: var(--faint);
  margin-left: 3px;
}

.slider-hint {
  font-size: 11.5px;
  color: var(--faint);
}

input[type='range'] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 22px;
  background: transparent;
  margin: 0;
  cursor: pointer;
}

input[type='range']::-webkit-slider-runnable-track {
  height: 8px;
  border-radius: 999px;
  background: linear-gradient(to right, var(--tone) var(--p, 0%), rgba(90, 70, 120, 0.14) var(--p, 0%));
}

input[type='range']::-moz-range-track {
  height: 8px;
  border-radius: 999px;
  background: rgba(90, 70, 120, 0.14);
}

input[type='range']::-moz-range-progress {
  height: 8px;
  border-radius: 999px;
  background: var(--tone);
}

input[type='range']::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  margin-top: -6px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--tone);
  box-shadow: 0 2px 5px rgba(60, 40, 90, 0.3);
  transition: transform 0.12s;
}

input[type='range']::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--tone);
  box-shadow: 0 2px 5px rgba(60, 40, 90, 0.3);
}

input[type='range']:active::-webkit-slider-thumb {
  transform: scale(1.15);
}

.seed-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13.5px;
  font-weight: 650;
}

.seed-row input {
  flex: 1;
  min-width: 0;
  height: 36px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: #fff;
  padding: 0 12px;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

.toggle {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
}

.toggle input {
  width: 18px;
  height: 18px;
  accent-color: var(--dusk);
}

/* ------------------------------------------------------------- charts */

.charts {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 18px;
}

.charts > .card {
  grid-column: span 3;
}

.charts > .card.wide {
  grid-column: span 4;
}

.charts > .card:nth-child(2) {
  grid-column: span 2;
}

.chart-block {
  display: grid;
  gap: 8px;
}

.chart-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 14px;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  font-size: 13px;
  font-weight: 650;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-variant-numeric: tabular-nums;
}

.legend-item i {
  width: 12px;
  height: 12px;
  border-radius: 4px;
}

.legend-item b {
  font-weight: 800;
}

.legend-item em {
  font-style: normal;
  color: var(--faint);
  font-weight: 600;
  font-size: 12px;
}

.legend-item.plain {
  color: var(--muted);
  font-weight: 600;
}

.chart-canvas {
  width: 100%;
  display: block;
  border-radius: 12px;
  touch-action: pan-y;
}

.chart-note {
  font-size: 12.5px;
  line-height: 1.4;
  color: var(--muted);
}

.seg {
  display: inline-flex;
  padding: 3px;
  gap: 2px;
  background: rgba(90, 70, 120, 0.09);
  border-radius: 999px;
}

.seg button {
  border: 0;
  background: transparent;
  padding: 5px 12px;
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 700;
  color: var(--muted);
}

.seg button.on {
  background: #fff;
  color: var(--ink);
  box-shadow: 0 1px 3px rgba(60, 40, 90, 0.25);
}

/* ------------------------------------------------------------ summary */

.summary {
  --tone: var(--dusk);
  display: grid;
  gap: 12px;
}

.summary.tone-good {
  --tone: var(--fruit);
}
.summary.tone-warn {
  --tone: #e0962b;
}
.summary.tone-bad {
  --tone: var(--red);
}

.verdict {
  border-left: 5px solid var(--tone);
  background: color-mix(in srgb, var(--tone) 10%, #fffdf8);
  border-radius: 6px 14px 14px 6px;
  padding: 10px 14px;
}

.verdict strong {
  display: block;
  font-size: 17px;
  letter-spacing: -0.01em;
  margin-bottom: 3px;
}

.verdict p {
  font-size: 13.5px;
  line-height: 1.45;
  color: var(--muted);
}

.story {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.story li {
  display: grid;
  grid-template-columns: 12px 1fr;
  gap: 9px;
  align-items: start;
  font-size: 13.5px;
  line-height: 1.42;
}

.story li i {
  width: 10px;
  height: 10px;
  margin-top: 5px;
  border-radius: 50%;
  background: var(--faint);
}

.story .mark-blue i {
  background: var(--blue);
}
.story .mark-red i {
  background: var(--red);
}
.story .mark-fruit i {
  background: var(--fruit);
}
.story .mark-wave i {
  background: var(--dusk);
}

.facts {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(112px, 1fr));
  gap: 8px;
  margin: 0;
}

.facts div {
  background: rgba(248, 241, 226, 0.65);
  border-radius: 12px;
  padding: 8px 10px;
}

.facts dt {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
}

.facts dd {
  margin: 1px 0 0;
  font-size: 19px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.facts small {
  display: block;
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.3;
}

/* ---------------------------------------------------------- inspector */

.inspector {
  --tone: var(--blue);
  position: absolute;
  right: 14px;
  top: 60px;
  width: 292px;
  max-height: calc(100% - 76px);
  overflow: auto;
  padding: 14px;
  display: grid;
  gap: 12px;
  border-radius: 20px;
  background: rgba(255, 253, 248, 0.94);
  backdrop-filter: blur(10px);
  box-shadow: 0 14px 34px -14px rgba(60, 40, 20, 0.5), 0 1px 3px rgba(60, 40, 20, 0.15);
  scrollbar-width: thin;
  animation: pop 0.22s ease-out;
}

.inspector.is-red {
  --tone: var(--red);
}

.inspector.is-dead {
  filter: saturate(0.5);
}

@keyframes pop {
  from {
    opacity: 0;
    transform: translateY(6px) scale(0.98);
  }
}

.inspector header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.portrait {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: radial-gradient(circle at 34% 28%, #fff 0 8%, color-mix(in srgb, var(--tone) 55%, #fff) 30%, var(--tone) 75%);
  box-shadow: 0 4px 10px -4px var(--tone);
  flex: none;
}

.who {
  flex: 1;
  min-width: 0;
}

.who h3 {
  font-size: 19px;
  letter-spacing: -0.01em;
  line-height: 1.15;
}

.pill {
  display: inline-block;
  margin-top: 3px;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 750;
  color: #fff;
  background: var(--tone);
}

.inspector .icon-btn {
  font-size: 22px;
  line-height: 1;
  width: 32px;
  height: 32px;
}

.action {
  display: grid;
  gap: 3px;
  padding: 10px 12px;
  border-radius: 14px;
  background: color-mix(in srgb, var(--tone) 9%, #fffdf8);
}

.action strong {
  font-size: 15px;
}

.action > span {
  font-size: 12.5px;
  line-height: 1.4;
  color: var(--muted);
}

.lock {
  margin-top: 6px;
  display: grid;
  gap: 4px;
}

.lock-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 12.5px;
  font-weight: 700;
}

.lock-row b {
  font-variant-numeric: tabular-nums;
}

.lock-row em,
.grid em,
.trait em {
  font-style: normal;
  color: var(--faint);
  font-weight: 600;
}

.bar {
  position: relative;
  height: 9px;
  border-radius: 999px;
  background: rgba(90, 70, 120, 0.13);
}

.bar i {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  border-radius: inherit;
  background: var(--tone);
}

.bar.energy i {
  background: linear-gradient(90deg, #ff9a6b, #ffd84f 45%, #6fd16a);
}

.bar s {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 3px;
  margin-left: -1px;
  border-radius: 2px;
  background: var(--ink);
}

.stat {
  display: grid;
  gap: 6px;
}

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin: 0;
}

.grid div {
  background: rgba(248, 241, 226, 0.65);
  border-radius: 12px;
  padding: 7px 10px;
}

.grid dt {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
}

.grid dd {
  margin: 1px 0 0;
  font-size: 15px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.inspector h4 {
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 5px;
}

.trait {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 10px;
  font-size: 13.5px;
  font-weight: 650;
  padding: 3px 0;
  font-variant-numeric: tabular-nums;
}

.trait b {
  font-weight: 800;
}

.trait em {
  min-width: 52px;
  text-align: right;
}

.family p {
  font-size: 13px;
  line-height: 1.45;
}

.family p + p {
  margin-top: 3px;
}

.muted {
  color: var(--muted);
}

.link {
  border: 0;
  background: none;
  padding: 0;
  font-weight: 800;
  color: var(--dusk);
  text-decoration: underline;
  text-underline-offset: 2px;
}

/* --------------------------------------------------------- responsive */

@media (max-width: 1180px) {
  .charts > .card,
  .charts > .card.wide,
  .charts > .card:nth-child(2) {
    grid-column: span 6;
  }
}

@media (max-width: 900px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .controls {
    position: static;
    max-height: none;
  }
  .charts > .card {
    grid-column: span 6;
  }
}

@media (max-width: 640px) {
  .app {
    padding: 12px 12px 32px;
  }
  .inspector {
    left: 10px;
    right: 10px;
    top: auto;
    bottom: 10px;
    width: auto;
    max-height: 62%;
  }
  .hud {
    max-width: 100%;
    top: 58px;
  }
  .stage-hint {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}

